<div class="dp-split"><section class="dp-card flush"><div class="sl-tw"><table class="sl-table dp-table"><thead><tr><th>Integration</th><th>Group</th><th>Status</th><th>Settings</th><th>Use (7 d)</th><th></th></tr></thead><tbody><?php foreach ((array) sl_get($d, 'rows', []) as $r): ?><tr><td><div class="sl-cell"><span class="ni sl-tile"><i class="ic <?= h($r['icon']) ?>" aria-hidden="true"></i></span><span class="fw5"><?= h($r['name']) ?></span></div></td><td class="sm"><?= h($r['group']) ?></td><td><span class="dp-lg"><i style="background:<?= $r['configured'] ? 'var(--dp-green)' : 'var(--dp-faint)' ?>"></i><?= $r['configured'] ? 'Configured' : 'Not set up' ?></span></td><td class="mono sm"><?= h($r['detail']) ?></td><td class="sm <?= !empty($r['failed7']) ? 'dp-warn' : '' ?>"><?= h($r['usage'] ?: '—') ?></td><td><a class="sl-btn ghost sm" href="<?= h($r['href']) ?>">Settings</a></td></tr><?php endforeach; ?></tbody></table></div></section>
<aside class="col g16"><section class="dp-card"><h2 class="dp-ct">Messages · 24 h</h2><?php foreach ((array) $d['channels'] as $ch => $c): ?><div class="dp-li"><span class="grow"><?= h(ucfirst($ch)) ?></span><span class="mono sm"><?= (int) $c['sent'] ?> sent · <span class="<?= $c['failed'] ? 'dp-warn' : '' ?>"><?= (int) $c['failed'] ?> failed</span></span></div><?php endforeach; ?><?php if (!$d['channels']): ?><span class="mut sm">Nothing sent in 24 hours.</span><?php endif; ?></section>
<section class="dp-card"><h2 class="dp-ct">API tokens</h2><?php foreach ((array) $d['tokens'] as $t): ?><div class="dp-li"><span class="grow clip"><?= h(($t->name ?: 'token') . ' · ' . trim((string) $t->who)) ?></span><span class="mut sm"><?= $t->last_used_at ? 'used ' . h(sl_ago($t->last_used_at)) : 'never used' ?></span></div><?php endforeach; ?><?php if (!$d['tokens']): ?><span class="mut sm">No active tokens.</span><?php endif; ?></section>
<section class="dp-card"><h2 class="dp-ct">Inbound webhooks</h2><?php foreach ((array) $d['webhooks'] as $w): ?><div class="dp-li"><span class="mono sm grow" style="word-break:break-all"><?= h($w->p) ?></span><span class="mut sm"><?= h(sl_ago($w->created_at)) ?></span></div><?php endforeach; ?><?php if (!$d['webhooks']): ?><span class="mut sm">None received.</span><?php endif; ?></section>
<section class="dp-card"><h2 class="dp-ct">CORS origins</h2><?php foreach ((array) $d['cors'] as $c): ?><div class="dp-li"><span class="mono sm grow"><?= h($c->origin) ?></span><span class="mut sm"><?= (int) $c->active ? 'active' : 'off' ?></span></div><?php endforeach; ?><?php if (!$d['cors']): ?><span class="mut sm">No origins listed · config allows <?= h(defined('CDP_API_ALLOWED_ORIGINS') ? (string) CDP_API_ALLOWED_ORIGINS : 'none') ?></span><?php endif; ?></section></aside></div>
<?php endif; ?>
</div>
<?= $dplEnd ?>
